92	    /**
93	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
94	     * event, so the events form a strictly ordered stream across every owner create.
95	     */
96	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
97	
98	    /**
99	     * The schema version stamped onto each structured {@code OWNER_CREATED} event. Version 2 adds
100	     * the {@code schemaVersion} field and carries the version-2 {@code memberId} read from the
101	     * owner's identity.
102	     */
103	    private static final int AUDIT_SCHEMA_VERSION = 2;
