116	    /**
117	     * Remembers, per {@code Idempotency-Key}, the id of the owner originally created for that key,
118	     * so a repeated create with an already-seen key returns the original owner instead of creating
119	     * a duplicate.
120	     */
121	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
