160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
164	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
165	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
166	            if (existingId != null) {
167	                Owner existing = this.clinicService.findOwnerById(existingId);
168	                if (existing != null) {
169	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
170	                }
171	            }
172	        }
173	        normalizeAddress(ownerFieldsDto);
174	        validateRequiredFields(ownerFieldsDto);
175	        validatePostcode(ownerFieldsDto);
176	        normalizeTelephone(ownerFieldsDto);
177	        normalizeEmail(ownerFieldsDto);
178	        rejectDuplicateIdentity(ownerFieldsDto);
179	        rejectCityAtCapacity(ownerFieldsDto.getCity());
180	        rejectFutureRegistrationDate(ownerFieldsDto);
181	        defaultRegistrationDate(ownerFieldsDto);
182	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
183	        HttpHeaders headers = new HttpHeaders();
184	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
185	        assignMemberId(owner);
186	        assignHouseholdId(owner);
187	        assignHouseholdMemberCount(owner);
188	        assignMembershipLevelCap(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
189	        assignNamesakeCount(owner);
190	        assignBulkSignupWarning(owner);
191	        assignCapacityWarning(owner);
192	        assignPossibleDuplicate(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
193	        this.clinicService.saveOwner(owner);
194	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
195	            this.idempotentCreates.put(idempotencyKey, owner.getId());
196	        }
197	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
198	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
199	        emitOwnerCreatedEvent(owner);
200	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
201	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
