207	    /**
208	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, in
209	     * addition to the human-readable audit line. The event is a schema-version-2 JSON object
210	     * {@code {seq, schemaVersion:2, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}
211	     * where {@code seq} is a monotonically increasing integer across every create (see
212	     * {@link #EVENT_SEQ}) and {@code schemaVersion} is {@link #AUDIT_SCHEMA_VERSION}.
213	     *
214	     * <p>The event carries the owner's <em>current</em> primary identifier under
215	     * {@code memberId}; see {@link #primaryIdentifier(Owner)} — the single place that decides which
216	     * field is the primary identifier.
217	     *
218	     * @param owner the just-created, already-persisted owner
219	     */
220	    private static void emitOwnerCreatedEvent(Owner owner) {
221	        long seq = EVENT_SEQ.incrementAndGet();
222	        String event = "{"
223	            + "\"seq\":" + seq
224	            + ",\"schemaVersion\":" + AUDIT_SCHEMA_VERSION
225	            + ",\"ownerId\":" + owner.getId()
226	            + ",\"memberId\":" + jsonString(primaryIdentifier(owner))
227	            + ",\"membershipLevel\":" + owner.getMembershipLevel()
228	            + ",\"event\":\"OWNER_CREATED\""
229	            + "}";
230	        AUDIT.info(event);
231	    }
232	
233	    /**
234	     * Returns the owner's current primary identifier carried by the structured {@code OWNER_CREATED}
235	     * event: the unified {@code memberId}.
236	     *
237	     * @param owner the owner whose primary identifier is required
238	     * @return the current primary identifier
239	     */
240	    private static String primaryIdentifier(Owner owner) {
241	        return owner.getMemberId();
242	    }
243	
244	    /**
245	     * Renders {@code value} as a JSON string literal (quoted and escaped), or the JSON {@code null}
246	     * literal when {@code value} is {@code null}.
247	     *
248	     * @param value the string to render, possibly {@code null}
249	     * @return a JSON string literal, or {@code null}
250	     */
251	    private static String jsonString(String value) {
252	        if (value == null) {
253	            return "null";
254	        }
255	        StringBuilder sb = new StringBuilder(value.length() + 2);
256	        sb.append('"');
257	        for (int i = 0; i < value.length(); i++) {
258	            char c = value.charAt(i);
259	            switch (c) {
260	                case '"' -> sb.append("\\\"");
261	                case '\\' -> sb.append("\\\\");
262	                case '\n' -> sb.append("\\n");
263	                case '\r' -> sb.append("\\r");
264	                case '\t' -> sb.append("\\t");
265	                default -> {
266	                    if (c < 0x20) {
267	                        sb.append(String.format("\\u%04x", (int) c));
268	                    }
269	                    else {
270	                        sb.append(c);
271	                    }
272	                }
273	            }
274	        }
275	        sb.append('"');
276	        return sb.toString();
277	    }
