361	    /**
362	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
363	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
364	     * Validation already rejects {@code null} values and the pattern-constrained fields
365	     * when blank, but {@code address} and {@code city} have no pattern, so a
366	     * whitespace-only value would otherwise slip through.
367	     *
368	     * @param ownerFieldsDto the submitted owner fields
369	     * @throws RequiredFieldsMissingException if any required field is missing or blank
370	     */
371	    /**
372	     * Common street-type abbreviations expanded during address normalization. Keys are the
373	     * upper-cased abbreviation tokens; values are their canonical expansions.
374	     */
375	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
376	        "ST", "STREET",
377	        "RD", "ROAD",
378	        "AVE", "AVENUE");
379	
380	    /**
381	     * Normalizes the submitted address on create, accepting either the structured form
382	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
383	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
384	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
385	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
386	     * values are written back onto the request.
387	     *
388	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
389	     * supplied, the flat {@code address} is set to the composed value — the normalized
390	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
391	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
392	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
393	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
394	     * required-field check can report it as missing.
395	     *
396	     * @param ownerFieldsDto the submitted owner fields
397	     */
398	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
399	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
400	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
401	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
402	        ownerFieldsDto.setAddressLine1(addressLine1);
403	        ownerFieldsDto.setAddressLine2(addressLine2);
404	        String composed;
405	        if (addressLine1 != null && !addressLine1.isBlank()) {
406	            composed = (addressLine2 != null && !addressLine2.isBlank())
407	                ? addressLine1 + " " + addressLine2
408	                : addressLine1;
409	        }
410	        else {
411	            composed = flat;
412	        }
413	        ownerFieldsDto.setAddress(composed);
414	    }
415	
416	    /**
417	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
418	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
419	     * expanded to its full form. A {@code null} value is returned unchanged.
420	     *
421	     * @param raw the address to canonicalize, possibly {@code null}
422	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
423	     */
424	    private static String normalizeAddress(String raw) {
425	        if (raw == null) {
426	            return null;
427	        }
428	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
429	        if (collapsed.isEmpty()) {
430	            return collapsed;
431	        }
432	        String[] tokens = collapsed.split(" ");
433	        StringBuilder sb = new StringBuilder(collapsed.length());
434	        for (int i = 0; i < tokens.length; i++) {
435	            if (i > 0) {
436	                sb.append(' ');
437	            }
438	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
439	        }
440	        return sb.toString();
441	    }
