443	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
444	        List<String> errors = new ArrayList<>();
445	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
446	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
447	        requireText("address", ownerFieldsDto.getAddress(), errors);
448	        requireText("city", ownerFieldsDto.getCity(), errors);
449	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
450	        if (!errors.isEmpty()) {
451	            throw new RequiredFieldsMissingException(errors);
452	        }
453	    }
454	
455	    private static void requireText(String field, String value, List<String> errors) {
456	        if (value == null || value.isBlank()) {
457	            errors.add(field);
458	        }
459	    }
