461	    /**
462	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
463	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
464	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
465	     */
466	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
467	        "NSW", new int[] {2000, 2099},
468	        "VIC", new int[] {3000, 3099},
469	        "QLD", new int[] {4000, 4099});
470	
471	    /**
472	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
473	     * {@code null} value is accepted. When present it has already been constrained to four digits
474	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
475	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
476	     * the postcode must fall within that region's inclusive range
477	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
478	     *
479	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
480	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
481	     *                                  city's region
482	     */
483	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
484	        String postcode = ownerFieldsDto.getPostcode();
485	        if (postcode == null) {
486	            return;
487	        }
488	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
489	            .regionFor(ownerFieldsDto.getCity());
490	        int[] range = REGION_POSTCODE_RANGE.get(region);
491	        if (range == null) {
492	            return;
493	        }
494	        int value = Integer.parseInt(postcode);
495	        if (value < range[0] || value > range[1]) {
496	            throw new InvalidPostcodeException(postcode);
497	        }
498	    }
499	
500	    /**
501	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
502	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
503	     * and echoed back in that form.
504	     *
505	     * @param ownerFieldsDto the submitted owner fields
506	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
507	     *                                        valid E.164 number
508	     */
509	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
510	        String e164 = toE164(ownerFieldsDto.getTelephone());
511	        if (e164 == null) {
512	            throw new RequiredFieldsMissingException(List.of("telephone"));
513	        }
514	        ownerFieldsDto.setTelephone(e164);
515	    }
516	
517	    /**
518	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
519	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
520	     * and country code are present they are kept; otherwise country code {@code '+61'} is
521	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
522	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
523	     * the national-number length must match the country: {@code '+61'} (Australia) requires
524	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
525	     *
526	     * @param raw the submitted telephone, possibly {@code null}
527	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
528	     */
529	    private static String toE164(String raw) {
530	        if (raw == null) {
531	            return null;
532	        }
533	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
534	        String digits;
535	        if (cleaned.startsWith("+")) {
536	            digits = cleaned.substring(1);
537	        } else {
538	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
539	            digits = "61" + national;
540	        }
541	        if (!digits.matches("[0-9]{8,15}")) {
542	            return null;
543	        }
544	        if (digits.startsWith("61")) {
545	            // Australia: exactly 9 national digits after the '+61' country code.
546	            if (digits.length() - 2 != 9) {
547	                return null;
548	            }
549	        } else if (digits.startsWith("1")) {
550	            // NANP: exactly 10 national digits after the '+1' country code.
551	            if (digits.length() - 1 != 10) {
552	                return null;
553	            }
554	        }
555	        return "+" + digits;
556	    }
