568	    /**
569	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
570	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
571	     * the parts may contain whitespace or a second {@code @}.
572	     */
573	    private static final Pattern EMAIL_PATTERN =
574	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
575	
576	    /**
577	     * Disposable email domains that are not accepted for an owner's email. A create whose email
578	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
579	     * rejected. Kept lower-cased to match the normalized email.
580	     */
581	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
582	        "mailinator.com",
583	        "tempmail.com",
584	        "guerrillamail.com");
585	
586	    /**
587	     * Normalizes the submitted email when present: the value is trimmed, required to be a
588	     * syntactically valid address, required not to use a disposable-email domain, and written back
589	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
590	     * left untouched — the field is optional.
591	     *
592	     * @param ownerFieldsDto the submitted owner fields
593	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
594	     *                               valid, or its domain is on the disposable-domain blocklist
595	     */
596	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
597	        String email = ownerFieldsDto.getEmail();
598	        if (email == null) {
599	            return;
600	        }
601	        String trimmed = email.strip();
602	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
603	            throw new InvalidEmailException(email);
604	        }
605	        String normalized = trimmed.toLowerCase(Locale.ROOT);
606	        String domain = normalized.substring(normalized.indexOf('@') + 1);
607	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
608	            throw new InvalidEmailException(email);
609	        }
610	        ownerFieldsDto.setEmail(normalized);
611	    }
