631	    /**
632	     * Establishes the effective registration date on create and rolls it onto a business day.
633	     * When the client does not supply a {@code registrationDate} it defaults to the server's
634	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
635	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
636	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
637	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
638	     * the memberId's fiscal-year segment and the daily create-limit).
639	     *
640	     * @param ownerFieldsDto the submitted owner fields
641	     */
642	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
643	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
644	        if (effective == null) {
645	            effective = LocalDate.now();
646	        }
647	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
648	    }
