650	    /**
651	     * Fixed public holidays that the business-day roll skips. A registration date that lands on
652	     * one of these dates is advanced to the next non-holiday business day (see
653	     * {@link #toBusinessDay}).
654	     */
655	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
656	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
657	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
658	        LocalDate.parse("2026-12-28"));
659	
660	    /**
661	     * Rolls a date forward to the next business day: any date that falls on a Saturday, a Sunday
662	     * or a listed public holiday is advanced one day at a time until it lands on a weekday that is
663	     * not a public holiday; any other date is returned unchanged.
664	     *
665	     * @param date the date to adjust
666	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday
667	     *         business day
668	     */
669	    private static LocalDate toBusinessDay(LocalDate date) {
670	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
671	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
672	            || PUBLIC_HOLIDAYS.contains(date)) {
673	            date = date.plusDays(1);
674	        }
675	        return date;
676	    }
