678	    /**
679	     * Assigns the owner's unified version-2 {@code memberId} on create, formatted
680	     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the version-2 region code — the fixed
681	     * {@code 'V2'} version tag (see {@link Owner#IDENTITY_VERSION}) prefixed onto the region derived
682	     * from the owner's postcode (preferring the postcode range, falling back to the city — the same
683	     * plain derivation that yields the owner's {@code locality}, see
684	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)});
685	     * FY is the two-digit fiscal year of the owner's (business-day-adjusted) {@code registrationDate}
686	     * on a fiscal year that starts on 1 July, zero-padded (matching the owner's {@code fiscalYear});
687	     * HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
688	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName}; and CHK is
689	     * a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>} — e.g.
690	     * {@code 'V2NSW27A1B2C3D45'}. The {@code 'V2'} tag makes every member id differ from the value
691	     * that version 1 produced. Because REGION and HASH8 both derive from the identity fields, two
692	     * owners in the same region and fiscal year share a member id only when their normalized
693	     * telephone and last name both match.
694	     *
695	     * <p>When the computed member id collides with an existing owner's {@code memberId}, it is
696	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
697	     * it unique among the existing owners, so distinct owners always receive distinct ids. Both
698	     * {@link #assignMemberId} and {@link #defaultRegistrationDate} must run first, so the owner's
699	     * {@code registrationDate} is already set.
700	     *
701	     * @param owner the owner being created (with its {@code postcode}, {@code city},
702	     *              {@code telephone}, {@code lastName} and {@code registrationDate} already set)
703	     */
704	    private void assignMemberId(Owner owner) {
705	        String region = Owner.IDENTITY_VERSION + org.springframework.samples.petclinic.mapper.LocalityLookup
706	            .regionFor(owner.getPostcode(), owner.getCity());
707	        String fy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
708	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
709	            .substring(0, 8).toUpperCase(Locale.ROOT);
710	        String core = region + fy + hash8;
711	        String base = core + luhnCheckDigit(core);
712	        Set<String> existing = this.clinicService.findAllOwners().stream()
713	            .map(Owner::getMemberId)
714	            .filter(Objects::nonNull)
715	            .collect(Collectors.toSet());
716	        String memberId = base;
717	        for (int n = 2; existing.contains(memberId); n++) {
718	            memberId = base + "-" + n;
719	        }
720	        owner.setMemberId(memberId);
721	    }
