723	    /**
724	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value},
725	     * ignoring any non-digit characters.
726	     *
727	     * @param value the value whose digits the check digit is computed over
728	     * @return the Luhn check digit, 0 to 9
729	     */
730	    private static int luhnCheckDigit(String value) {
731	        int sum = 0;
732	        boolean dbl = true;
733	        for (int i = value.length() - 1; i >= 0; i--) {
734	            char c = value.charAt(i);
735	            if (c < '0' || c > '9') {
736	                continue;
737	            }
738	            int d = c - '0';
739	            if (dbl) {
740	                d *= 2;
741	                if (d > 9) {
742	                    d -= 9;
743	                }
744	            }
745	            sum += d;
746	            dbl = !dbl;
747	        }
748	        return (10 - (sum % 10)) % 10;
749	    }
