876	    /**
877	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
878	     * {@link #rejectDuplicateIdentity}, so this owner is not a hard duplicate. A declared household
879	     * member (one that opted in via {@code sharesHousehold}) is never flagged: it is an
880	     * acknowledged member of the household, not a suspected duplicate, so {@code possibleDuplicate}
881	     * is {@code false}. Otherwise it is a <em>possible</em> duplicate when an existing owner shares
882	     * its {@code soundex(lastName)} (see {@link Owner#soundex}) and its {@code postcode} but has a
883	     * <em>different</em> {@code identityKey} (so it was not already rejected as a hard duplicate —
884	     * typically a different telephone or email): {@code possibleDuplicate} is set {@code true} and
885	     * {@code possibleDuplicateOf} to that owner's id (the earliest such owner by id when several
886	     * match). Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf}
887	     * is left unset. The scan is taken over the existing owners before this one is persisted.
888	     *
889	     * @param owner the owner being created (with its {@code lastName}, {@code postcode},
890	     *              already-normalized {@code telephone} and {@code email} set)
891	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
892	     */
893	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
894	        if (declaredHouseholdMember) {
895	            owner.setPossibleDuplicate(false);
896	            owner.setPossibleDuplicateOf(null);
897	            return;
898	        }
899	        String lastName = owner.getLastName();
900	        String postcode = owner.getPostcode();
901	        Integer matchId = null;
902	        if (lastName != null && postcode != null) {
903	            String soundex = Owner.soundex(lastName);
904	            String identityKey = owner.getIdentityKey();
905	            matchId = this.clinicService.findAllOwners().stream()
906	                .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName())))
907	                .filter(existing -> postcode.equals(existing.getPostcode()))
908	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
909	                .map(Owner::getId)
910	                .filter(id -> id != null)
911	                .min(Integer::compareTo)
912	                .orElse(null);
913	        }
914	        owner.setPossibleDuplicate(matchId != null);
915	        owner.setPossibleDuplicateOf(matchId);
