918	    /**
919	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
920	     *
921	     * @param value the string to hash
922	     * @return the 64-character lower-case hex digest
923	     */
924	    private static String sha256Hex(String value) {
925	        try {
926	            byte[] digest = MessageDigest.getInstance("SHA-256")
927	                .digest(value.getBytes(StandardCharsets.UTF_8));
928	            StringBuilder sb = new StringBuilder(digest.length * 2);
929	            for (byte b : digest) {
930	                sb.append(String.format("%02x", b));
931	            }
932	            return sb.toString();
933	        }
934	        catch (NoSuchAlgorithmException e) {
935	            throw new IllegalStateException("SHA-256 not available", e);
936	        }
937	    }
