940	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
941	     * owner (owners flagged deleted are ignored). The key is the SHA-256 hex of
942	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
943	     * {@link Owner#identityKey}), and a create is a duplicate only when its <em>whole</em> key
944	     * matches an existing owner's. Because the telephone is part of the key, two owners sharing a
945	     * last name and postcode but with different telephones have different identity keys and are
946	     * both allowed (the second is flagged a soft match, see {@link #assignPossibleDuplicate}); only
947	     * an exact full-key match is rejected. The submitted telephone and email have already been
948	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and each existing
949	     * owner's key is computed the same way so differing input formats collapse to the same value.
950	     *
951	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
952	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
953	     *                                    whole identity key
954	     */
955	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
956	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
957	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
958	        boolean duplicate = this.clinicService.findAllOwners().stream()
959	            .filter(owner -> !owner.isDeleted())
960	            .map(Owner::getIdentityKey)
961	            .anyMatch(identityKey::equals);
962	        if (duplicate) {
963	            throw new DuplicateIdentityException(identityKey);
964	        }
965	    }
