1032	     * business day as their {@code registrationDate}. The day counted against is this create's
1033	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
1034	     * so owners are counted per adjusted business day. The count is taken before this owner is
1035	     * persisted.
1036	     *
1037	     * @param businessDay the effective, business-day-adjusted registration date of this create
1038	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
1039	     */
1040	    private void rejectDailyLimit(LocalDate businessDay) {
1041	        long count = this.clinicService.findAllOwners().stream()
1042	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
1043	            .count();
1044	        if (count >= DAILY_LIMIT) {
1045	            throw new DailyOwnerLimitExceededException(businessDay);
1046	        }
1047	    }
