1049	    /**
1050	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
1051	     * every internal run of whitespace is collapsed to a single space, and the result is
1052	     * lower-cased. A {@code null} value collapses to the empty string.
1053	     *
1054	     * @param value the value to canonicalize, possibly {@code null}
1055	     * @return the collapsed, lower-cased value
1056	     */
1057	    private static String collapse(String value) {
1058	        if (value == null) {
1059	            return "";
1060	        }
1061	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1062	    }
