427	        if (this.telephone == null || !this.telephone.startsWith("+")
428	                || !this.telephone.substring(1).matches("[0-9]+")) {
429	            return this.telephone;
430	        }
431	        String digits = this.telephone.substring(1);
432	        String countryCode;
433	        if (digits.startsWith("61")) {
434	            countryCode = "61";
435	        } else if (digits.startsWith("1")) {
436	            countryCode = "1";
437	        } else {
438	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
439	        }
440	        String national = digits.substring(countryCode.length());
441	        StringBuilder display = new StringBuilder("+").append(countryCode);
442	        for (int i = 0; i < national.length(); i += 3) {
443	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
444	        }
445	        return display.toString();
446	    }
