464	    /**
465	     * The fixed version tag mixed into every derived owner identifier so that the version-2
466	     * identity ({@code identityKey}, {@code memberId} and {@code householdId}) never reproduces a
467	     * value produced under version 1. It is an internal component of the identifiers only and never
468	     * leaks into the user-facing {@code locality}, {@code timezone} or owner-segment region.
469	     */
470	    public static final String IDENTITY_VERSION = "V2";
471	
472	    /**
473	     * Computes the consolidated version-2 {@code identityKey} for the given identity-bearing fields:
474	     * the lower-case hex SHA-256 digest of
475	     * {@code IDENTITY_VERSION + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
476	     * The fixed {@code 'V2'} version tag (see {@link #IDENTITY_VERSION}) is mixed in so the key differs
477	     * from the version-1 key; the {@code email} is lower-cased (empty when absent) and the
478	     * {@code lastName} is reduced to its Soundex code (see {@link #soundex}). The {@code telephone} is
479	     * expected already normalized to E.164 form.
480	     *
481	     * @param telephone the owner's normalized (E.164) telephone, possibly {@code null}
482	     * @param email     the owner's email, possibly {@code null}
483	     * @param lastName  the owner's last name, possibly {@code null}
484	     * @return the lower-case hex SHA-256 identity key
485	     */
486	    public static String identityKey(String telephone, String email, String lastName) {
487	        String telephonePart = telephone == null ? "" : telephone;
488	        String emailPart = email == null ? "" : email.toLowerCase(Locale.ROOT);
489	        return sha256Hex(IDENTITY_VERSION + "|" + telephonePart + "|" + emailPart + "|" + soundex(lastName));
490	    }
491	
492	    /**
493	     * Returns the American Soundex code of {@code value}: the first letter followed by three
494	     * digits encoding the remaining consonants (b,f,p,v→1; c,g,j,k,q,s,x,z→2; d,t→3; l→4; m,n→5;
495	     * r→6), where vowels and {@code h}/{@code w} are not coded, adjacent letters with the same
496	     * code collapse to one (and a code repeated across an {@code h}/{@code w} is treated as
497	     * adjacent), and the result is right-padded with zeros to length four. A {@code null} or
498	     * letter-free value yields the empty string.
499	     *
500	     * @param value the value to encode, possibly {@code null}
501	     * @return the four-character Soundex code, or the empty string when there is no letter
502	     */
503	    public static String soundex(String value) {
504	        if (value == null) {
505	            return "";
506	        }
507	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
508	        if (letters.isEmpty()) {
509	            return "";
510	        }
511	        StringBuilder code = new StringBuilder();
512	        code.append(letters.charAt(0));
513	        char previous = soundexDigit(letters.charAt(0));
514	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
515	            char c = letters.charAt(i);
516	            if (c == 'H' || c == 'W') {
517	                continue;
518	            }
519	            char digit = soundexDigit(c);
520	            if (digit != '0' && digit != previous) {
521	                code.append(digit);
522	            }
523	            previous = (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y')
524	                ? '0' : digit;
525	        }
526	        while (code.length() < 4) {
527	            code.append('0');
528	        }
529	        return code.toString();
530	    }
531	
532	    private static char soundexDigit(char c) {
533	        switch (c) {
534	            case 'B': case 'F': case 'P': case 'V':
535	                return '1';
536	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
537	                return '2';
538	            case 'D': case 'T':
539	                return '3';
540	            case 'L':
541	                return '4';
542	            case 'M': case 'N':
543	                return '5';
544	            case 'R':
545	                return '6';
546	            default:
547	                return '0';
548	        }
549	    }
550	
551	    private static String sha256Hex(String value) {
552	        try {
553	            byte[] digest = MessageDigest.getInstance("SHA-256")
554	                .digest(value.getBytes(StandardCharsets.UTF_8));
555	            StringBuilder sb = new StringBuilder(digest.length * 2);
556	            for (byte b : digest) {
557	                sb.append(String.format("%02x", b));
558	            }
559	            return sb.toString();
560	        }
561	        catch (NoSuchAlgorithmException e) {
562	            throw new IllegalStateException("SHA-256 not available", e);
563	        }
564	    }
